const API_BASE_URL = 'https://TU_SUBDOMINIO.xano.io/api:TU_API_KEY';
const USUARIOS_URL = `${API_BASE_URL}/usuarios`;
const PRODUCTOS_URL = `${API_BASE_URL}/productos`;

class ApiService {

  async login(credentials) {
    const response = await fetch(`${USUARIOS_URL}/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(credentials)
    });

    const data = await response.json();

    if (!response.ok) throw new Error(data.message || 'Error al iniciar sesión');

    localStorage.setItem('authToken', data.authToken);
    localStorage.setItem('user', JSON.stringify(data));
    return data;
  }

  logout() {
    localStorage.removeItem('authToken');
    localStorage.removeItem('user');
  }

  getAuthToken() {
    return localStorage.getItem('authToken');
  }

  // ✅ PRODUCTOS
  async getAllProductos() {
    const response = await fetch(PRODUCTOS_URL);
    if (!response.ok) throw new Error('Error al obtener productos');
    return await response.json();
  }

  async getProductoById(id) {
    const response = await fetch(`${PRODUCTOS_URL}/${id}`);
    if (!response.ok) throw new Error('Producto no encontrado');
    return await response.json();
  }

  // ✅✅✅ CHECKOUT CON DESCUENTO DE STOCK EN XANO
  async checkout(cartItems) {
    const response = await fetch(`${API_BASE_URL}/checkout`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        items: cartItems.map(item => ({
          id: item.id,
          quantity: item.quantity
        }))
      })
    });

    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.message || 'Error al procesar el pago');
    }

    return data;
  }
}

const apiServiceInstance = new ApiService();
export default apiServiceInstance;
